// Writes engine/crates/styk-core/src/text/names_data.rs from the language and Macintosh encoding tables of the
// vendored opentype.js, so the Rust name-table reader cannot differ from them by a typing error.
//   node engine/crates/styk-core/tests/fixtures/text/names-data.mjs
import {readFileSync, writeFileSync} from 'node:fs';
const source = readFileSync(new URL('../../../../../../vendor/text/opentype.mjs', import.meta.url), 'utf8');
const table = name => {
  const start = source.indexOf(`var ${name} = {`);
  if (start < 0) throw new Error(`missing ${name}`);
  const open = source.indexOf('{', start);
  let depth = 0, end = open;
  for (; end < source.length; end++) {
    if (source[end] === '{') depth++;
    else if (source[end] === '}' && --depth === 0) break;
  }
  return new Function(`return (${source.slice(open, end + 1)})`)();
};
const macLanguages = table('macLanguages'), windowsLanguages = table('windowsLanguages'),
  macScriptEncodings = table('macScriptEncodings'), macLanguageEncodings = table('macLanguageEncodings'),
  eightBit = table('eightBitMacEncodings');
const str = value => JSON.stringify(value);
const numeric = (name, dict) => `pub(crate) const ${name}: &[(u16, &str)] = &[\n${Object.keys(dict).map(Number).sort((a, b) => a - b)
  .map(key => `    (${key}, ${str(dict[key])}),`).join('\n')}\n];\n`;
let out = `//! Generated by tests/fixtures/text/names-data.mjs from vendor/text/opentype.mjs: do not edit.\n\n`;
out += numeric('MAC_LANGUAGES', macLanguages) + '\n' + numeric('WINDOWS_LANGUAGES', windowsLanguages) + '\n';
out += numeric('MAC_SCRIPT_ENCODINGS', macScriptEncodings) + '\n' + numeric('MAC_LANGUAGE_ENCODINGS', macLanguageEncodings) + '\n';
out += `/// The upper half (0x80 to 0xff) of each eight-bit Macintosh encoding, as UTF-16 code units. A table shorter than 128 units
/// (x-mac-cyrillic has 127) yields the text "undefined" for the missing code, as opentype.js's string concatenation does.\npub(crate) const EIGHT_BIT_MAC: &[(&str, &[u16])] = &[\n`;
for (const [name, text] of Object.entries(eightBit)) {
  const units = Array.from({length: text.length}, (_, i) => text.charCodeAt(i));
  if (units.length > 128) throw new Error(`${name} has ${units.length} units`);
  out += `    (${str(name)}, &[${units.map(u => '0x' + u.toString(16)).join(', ')}]),\n`;
}
out += '];\n';
writeFileSync(new URL('../../../src/text/names_data.rs', import.meta.url), out);
console.log('wrote names_data.rs');
